+  @Test
+  public void testFieldGlobbing() throws Exception  {
+    SolrServer server = getSolrServer();
+
+    SolrInputDocument doc = new SolrInputDocument();
+    doc.addField("id", "testFieldGlobbing");
+    doc.addField("x_s", "x");
+    doc.addField("y_s", "y");
+    doc.addField("z_s", "z");
+    server.add(doc);
+    server.commit();
+
+    // id and glob
